def separate_paren_groups(paren_string: str) -> List[str]:
    if not isinstance(paren_string, str):
        return []

    result = []
    current_group = []
    balance = 0

    for char in paren_string:
        if char == '(':
            balance += 1
            current_group.append(char)
        elif char == ')':
            if balance > 0:
                balance -= 1
                current_group.append(char)
                if balance == 0:
                    result.append("".join(current_group))
                    current_group = []
            # If balance is 0, an extra ')' is ignored to maintain robustness

    return result
